        const panel = document.getElementById('overlayPanel');
        const backdrop = document.getElementById('overlayBackdrop');
        const closeBtn = document.getElementById('overlayClose');

        function openPanel() {
            panel.classList.add('show');
            backdrop.classList.add('show');
            panel.setAttribute('aria-hidden', 'false');
            backdrop.setAttribute('aria-hidden', 'false');
            document.body.style.overflow = 'hidden';
        }

        function closePanel() {
            panel.classList.remove('show');
            backdrop.classList.remove('show');
            panel.setAttribute('aria-hidden', 'true');
            backdrop.setAttribute('aria-hidden', 'true');
            document.body.style.overflow = '';
        }

        readBtn && readBtn.addEventListener('click', function(e) {
            e.preventDefault();
            openPanel();
        });
        closeBtn && closeBtn.addEventListener('click', closePanel);
        backdrop && backdrop.addEventListener('click', closePanel);
        // close with Escape
        document.addEventListener('keydown', function(e) {
            if (e.key === 'Escape' && panel.classList.contains('show')) closePanel();
        });
    })();
    </script>
    <script src="jquery-3.6.4.min.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script>
    <script src="../js/contactModalScript.js"></script>

    <!-- load reCAPTCHA API last, using the global onload callback defined in contactModalScript.js -->
    <script src="https://www.google.com/recaptcha/api.js?onload=onloadCallback&render=explicit" async defer>
    </script>
</body>

</html>